import{d as u,C as a,o as c,c as y,j as n,a as t,E as i,a3 as o}from"./chunks/framework.Q4yG9rk_.js";const f=JSON.parse('{"title":"文言传","description":"专释乾坤两卦的传——从元亨利贞与六爻时位，到坤道承载与敬义立身，读懂以传解经的义理样板。","frontmatter":{"title":"文言传","description":"专释乾坤两卦的传——从元亨利贞与六爻时位，到坤道承载与敬义立身，读懂以传解经的义理样板。","category":"guide","aliases":["文言传","文言","wen yan zhuan"],"source":["《周易·文言传》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/shi-yi/wen-yan-zhuan.md","filePath":"yijing/shi-yi/wen-yan-zhuan.md","lastUpdated":1790587309000}'),b={name:"yijing/shi-yi/wen-yan-zhuan.md"},k=u({...b,setup(p){const r=[{id:"qian-01",label:"一、元亨利贞四德",showLabel:!0,sentences:[["文言曰：“元者，善之长也；亨者，嘉之会也；利者，义之和也；贞者，事之干也。”"],["君子",{text:"体仁",glossary:"g02"},"，足以长人；嘉会，足以合礼；利物，足以和义；",{text:"贞固",glossary:"g03"},"，足以干事。君子行此四者，故曰：乾，",{text:"元亨利贞",glossary:"g01"},"。"]],note:["《文言》先解乾的四种德性：元是善之长，亨是嘉之会，利是义之和，贞是事之干。君子体行仁德便足以长人，会合礼义便足以合礼，利物便足以和义，守正坚固便足以干事；君子践行这四者，所以说「乾，元亨利贞」。"]},{id:"qian-02",label:"二、初九潜龙勿用",showLabel:!0,sentences:[["初九曰：“",{text:"潜龙",glossary:"g04"},"勿用。”何谓也？子曰：“龙德而隐者也。不易乎世，不成乎名；遁世而无闷，不见是而无闷；乐则行之，忧则违之；确乎其不可拔，乾龙也。”"]],note:["初九「潜龙勿用」是什么意思？孔子说：这是有龙之德而隐伏的人。他不为世俗所移，不求成名；隐遁于世而不郁闷，不被认可也不郁闷；可做就做，不可做就退；确然坚定而不可动摇——这就是乾之龙。"]},{id:"qian-03",label:"三、九二见龙在田",showLabel:!0,sentences:[["九二曰：“",{text:"见龙",glossary:"g05"},"在田，利见",{text:"大人",glossary:"g07"},"。”何谓也？子曰：“龙德而正中者也。庸言之信，庸行之谨，闲邪存其诚，善世而不伐，德博而化。君德也。”"]],note:["九二「见龙在田，利见大人」是什么意思？孔子说：这是有龙之德而居中正位的人。平常说话守信，平常行事谨慎，防止邪念而存其诚，造福世人而不自夸，德泽广博而能化人——这就是君德。"]},{id:"qian-04",label:"四、九三乾乾夕惕",showLabel:!0,sentences:[["九三曰：“君子终日乾乾，夕惕若，厉无咎。”何谓也？子曰：“君子进德修业，忠信，所以进德也；修辞立其诚，所以居业也。知至至之，可与几也；知终终之，可与存义也。”"],["是故，居上位而不骄，在下位而不忧。故乾乾，因其时而惕，虽危而无咎矣。"]],note:["九三「君子终日乾乾，夕惕若，厉无咎」是什么意思？孔子说：君子进德修业——忠信，是用来进德的；修饰言辞而确立其诚，是用来居业的。知道该到就到来，可以与他谈几微；知道该止就止住，可以与他存守道义。所以居上位而不骄，在下位而不忧；因而勤勉不息，随时而警惕，虽处危境也没有过错。"]},{id:"qian-05",label:"五、九四或跃在渊",showLabel:!0,sentences:[["九四曰：“或跃在渊，无咎。”何谓也？子曰：“上下无常，非为邪也；进退无恒，非离群也。君子进德修业，欲及时也，故无咎。”"]],note:["九四「或跃在渊，无咎」是什么意思？孔子说：上下没有一定，不是出于邪念；进退没有常规，不是背离同群。君子进德修业，是想及时而动，所以没有过错。"]},{id:"qian-06",label:"六、九五飞龙在天",showLabel:!0,sentences:[["九五曰：“飞龙在天，利见",{text:"大人",glossary:"g07"},"。”何谓也？子曰：“同声相应，同气相求；水流湿，火就燥；云从龙，风从虎。圣人作而万物覩，本乎天者亲上，本乎地者亲下，则各从其类也。”"]],note:["九五「飞龙在天，利见大人」是什么意思？孔子说：同声相应，同气相求；水流向湿处，火走向燥处；云随龙，风随虎。圣人兴起而万物显见；本于天的亲附于上，本于地的亲附于下——各自依类相从。"]},{id:"qian-07",label:"七、上九亢龙有悔",showLabel:!0,sentences:[["上九曰：“亢龙有悔。”何谓也？子曰：“贵而无位，高而无民，贤人在下位而无辅，是以动而有悔也。”"]],note:["上九「亢龙有悔」是什么意思？孔子说：尊贵而没有实位，居高而没有民众，贤人在下位而无人辅佐，因此一动就有悔恨。"]},{id:"qian-08",label:"八、六龙之人事",showLabel:!0,sentences:[["乾龙勿用，下也；",{text:"见龙",glossary:"g05"},"在田，时舍也；终日乾乾，行事也；或跃在渊，自试也；飞龙在天，上治也；亢龙有悔，穷之灾也；乾元用九，天下治也。"]],note:["（这一段以人事分说六龙：）潜龙勿用，是处境低下；见龙在田，是随时而止；终日乾乾，是行事；或跃在渊，是自试其才；飞龙在天，是居上而治；亢龙有悔，是穷极之灾；乾元用九，则天下大治。"]},{id:"qian-09",label:"九、六龙之天道",showLabel:!0,sentences:[["乾龙勿用，阳气潜藏；",{text:"见龙",glossary:"g05"},"在田，天下文明；终日乾乾，与时偕行；或跃在渊，乾道乃革；飞龙在天，乃位乎天德；亢龙有悔，与时偕极；乾元用九，乃见天则。"]],note:["（这一段以天道分说六龙：）潜龙勿用，是阳气潜藏；见龙在田，是天下文明；终日乾乾，是随时而行；或跃在渊，是乾道变革；飞龙在天，是位居天德；亢龙有悔，是随时而极；乾元用九，是天道的法则于此显现。"]},{id:"qian-10",label:"十、乾元与性情",showLabel:!0,sentences:[["乾元者，始而亨者也；利贞者，性情也。乾始能以美利利天下，不言所利。大矣哉！大哉乾乎！刚健中正，纯粹精也。"],["六爻发挥，旁通情也；时乘六龙，以御天也；云行雨施，天下平也。"]],note:["乾元是创始而通达，利贞是它的性情。乾以美利利天下，却不言自己所利——伟大啊！刚健中正，纯粹而精。六爻发挥，旁通其情；随时乘驾六龙以御天，云行雨施而天下太平。"]},{id:"qian-11",label:"十一、成德为行",showLabel:!0,sentences:[["君子以成德为行，日可见之行也。潜之为言也，隐而未见，行而未成，是以君子弗用也。"]],note:["君子以成就德行为行，日日可见于行动。而「潜」的意思在于：隐而未现、行而未成，所以君子此时不用。"]},{id:"qian-12",label:"十二、学聚问辩",showLabel:!0,sentences:[["君子学以聚之，问以辩之，宽以居之，仁以行之。",{text:"见龙",glossary:"g05"},"在田，利见",{text:"大人",glossary:"g07"},"，君德也。"]],note:["君子以学来聚积，以问来辨明，以宽厚来安处，以仁德来践行。见龙在田、利见大人，正是君德。"]},{id:"qian-13",label:"十三、九三重刚",showLabel:!0,sentences:[["九三，重刚而不中，上不在天，下不在田，故乾乾，因其时而惕，虽危无咎矣。"]],note:["九三，重刚而不中，上不在天，下不在田，所以要勤勉不息、随时警惕，虽处危境而无咎。"]},{id:"qian-14",label:"十四、九四重刚",showLabel:!0,sentences:[["九四，重刚而不中，上不在天，下不在田，中不在人，故或之；或之者，疑之也，故无咎。"]],note:["九四，重刚而不中，上不在天，下不在田，中不在人，所以用「或」；「或」就是疑——疑而后动，所以无咎。"]},{id:"qian-15",label:"十五、大人合天",showLabel:!0,sentences:[["夫",{text:"大人",glossary:"g07"},"者，与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶。先天下而天弗违，后天而奉天时。"]],note:["所谓大人，与天地合其德，与日月合其明，与四时合其序，与鬼神合其吉凶。先于天而天不违他，后于天而奉行天时。"]},{id:"qian-16",label:"十六、亢之为言",showLabel:!0,sentences:[["亢之为言也，知进而不知退，知存而不知亡，知得而不知丧。其唯圣人乎？知进退存亡，而不失其正者，其为圣人乎！"]],note:["「亢」的意思在于：只知进而不知退，只知存而不知亡，只知得而不知丧。大概只有圣人吧——知道进退存亡，而不失其正，这就是圣人吧！"]}],s=[{id:"g01",term:"元亨利贞",pinyin:"yuán hēng lì zhēn",meaning:"文言分别解释为善之长、嘉之会、义之和、事之干。四字不是四个孤立吉兆，而是一条从发端、通达、合宜到守正的成事结构。"},{id:"g02",term:"体仁",pinyin:"tǐ rén",meaning:"以仁为体，把仁落实为自身的行动，因此足以长养、成全他人，而不只是口头谈仁。"},{id:"g03",term:"贞固",pinyin:"zhēn gù",meaning:"守住原则与根本。「固」不是僵硬地拒绝变化，而是在方法变化时仍不失诚实、责任与分寸。"},{id:"g04",term:"潜龙",pinyin:"qián lóng",meaning:"德性与能力尚在隐伏、行动尚未完成的阶段。勿用不是不学习，而是不把未成熟强行推到台前。"},{id:"g05",term:"见龙",pinyin:"xiàn lóng",meaning:"德性开始显现并影响周围。其基础是庸言可信、庸行谨慎、善世而不自伐。"},{id:"g06",term:"知几",pinyin:"zhī jī",meaning:"知道事情将动未动的微小征兆。知至至之、知终终之，都是对时机和边界的辨认。"},{id:"g07",term:"大人",pinyin:"dà rén",meaning:"不是单指地位高的人，而是能与天地、日月、四时相合，先后皆能奉时而行的德性与担当。"},{id:"g08",term:"至柔动刚",pinyin:"zhì róu dòng gāng",meaning:"坤外在柔顺，实际行动却有承载和完成的力量。柔并不等于弱，静也不等于没有方向。"},{id:"g09",term:"承天时行",pinyin:"chéng tiān shí xíng",meaning:"承接规律并依时行动，不是盲从天意，而是看清条件、角色和时势后完成自己的工作。"},{id:"g10",term:"含章",pinyin:"hán zhāng",meaning:"内有才华、美德和光明，却不急于显露或争功。含不是压抑才能，而是不让自我证明取代事情本身。"},{id:"g11",term:"括囊",pinyin:"kuò náng",meaning:"扎紧袋口，象征天地闭塞或时机不宜时的谨慎收敛；不能把它滥用为逃避应尽责任的借口。"},{id:"g12",term:"黄中通理",pinyin:"huáng zhōng tōng lǐ",meaning:"内守中正而通达事理，正位居体，内在之美最终流布于言行并落实为事业。"}],g=[{id:"kun-01",label:"一、坤德柔刚",showLabel:!0,sentences:[["文言曰：“坤至柔，而动也刚；至静，而德方；后得主而有常；含万物而化光。坤其道顺乎？承天而时行。”"],["积善之家，必有馀庆；积不善之家，必有馀殃。臣弑其君，子弑其父，非一朝一夕之故，其所由来者渐矣，由辨之不早辨也。履霜坚冰至，盖言顺也。"]],note:["坤至为柔顺，可动起来却刚健；至为安静，而其德方正；后于乾而得主而有常，含容万物而化育光明。坤之道就是顺吧？它承奉天道而按时运行。积善之家必有余庆，积不善之家必有余殃。臣杀君、子杀父，不是一朝一夕的缘故，它的由来是渐积而成的——只因没有及早辨察。履霜而知坚冰将至，说的就是这种顺。"]},{id:"kun-02",label:"二、直方大",showLabel:!0,sentences:[["直其正也，方其义也。君子敬以直内，义以方外，敬义立而德不孤。“直，方，大，不习无不利”，则不疑其所行也。"],["阴虽有美，含之；以从王事，弗敢成也。地道也，妻道也，臣道也。地道无成，而代有终也。"]],note:["「直」是它的正，「方」是它的义。君子以敬来端正内心，以义来规范外行；敬与义既立，其德便不孤立，故说「直方大，不习无不利」，就是对自己的所作所为不疑惑。阴虽有美却含藏不露，以从王事而不敢自成其功——这是地道、妻道、臣道。地道不居功，却代乾而成其终。"]},{id:"kun-03",label:"三、括囊与黄中",showLabel:!0,sentences:[["天地变化，草木蕃；天地闭，贤人隐。“",{text:"括囊",glossary:"g11"},"；无咎，无誉”，盖言谨也。"],["君子",{text:"黄中通理",glossary:"g12"},"，正位居体，美在其中，而畅于四支，发于事业，美之至也。"]],note:["天地变化，草木繁茂；天地闭塞，贤人隐退。所以说「括囊，无咎，无誉」——扎紧袋口，讲的是谨慎。君子黄中通理、正位居体，美在内心而畅达于四肢、发显于事业——这是美的极致。"]},{id:"kun-04",label:"四、龙战玄黄",showLabel:!0,sentences:[["阴疑于阳，必战。为其嫌于无阳也，故称龙焉；犹未离其类也，故称血焉。夫玄黄者，天地之杂也，天玄而地黄。"]],note:["阴与阳势均便必有一战。因为阴盛得几乎像没有阳，所以称它为「龙」；因为它尚未离开其同类，所以称它为「血」。至于玄黄，是天地相杂之色——天玄而地黄。"]}],h=[{id:"g01",term:"元亨利贞",pinyin:"yuán hēng lì zhēn",meaning:"文言分别解释为善之长、嘉之会、义之和、事之干。四字不是四个孤立吉兆，而是一条从发端、通达、合宜到守正的成事结构。"},{id:"g02",term:"体仁",pinyin:"tǐ rén",meaning:"以仁为体，把仁落实为自身的行动，因此足以长养、成全他人，而不只是口头谈仁。"},{id:"g03",term:"贞固",pinyin:"zhēn gù",meaning:"守住原则与根本。「固」不是僵硬地拒绝变化，而是在方法变化时仍不失诚实、责任与分寸。"},{id:"g04",term:"潜龙",pinyin:"qián lóng",meaning:"德性与能力尚在隐伏、行动尚未完成的阶段。勿用不是不学习，而是不把未成熟强行推到台前。"},{id:"g05",term:"见龙",pinyin:"xiàn lóng",meaning:"德性开始显现并影响周围。其基础是庸言可信、庸行谨慎、善世而不自伐。"},{id:"g06",term:"知几",pinyin:"zhī jī",meaning:"知道事情将动未动的微小征兆。知至至之、知终终之，都是对时机和边界的辨认。"},{id:"g07",term:"大人",pinyin:"dà rén",meaning:"不是单指地位高的人，而是能与天地、日月、四时相合，先后皆能奉时而行的德性与担当。"},{id:"g08",term:"至柔动刚",pinyin:"zhì róu dòng gāng",meaning:"坤外在柔顺，实际行动却有承载和完成的力量。柔并不等于弱，静也不等于没有方向。"},{id:"g09",term:"承天时行",pinyin:"chéng tiān shí xíng",meaning:"承接规律并依时行动，不是盲从天意，而是看清条件、角色和时势后完成自己的工作。"},{id:"g10",term:"含章",pinyin:"hán zhāng",meaning:"内有才华、美德和光明，却不急于显露或争功。含不是压抑才能，而是不让自我证明取代事情本身。"},{id:"g11",term:"括囊",pinyin:"kuò náng",meaning:"扎紧袋口，象征天地闭塞或时机不宜时的谨慎收敛；不能把它滥用为逃避应尽责任的借口。"},{id:"g12",term:"黄中通理",pinyin:"huáng zhōng tōng lǐ",meaning:"内守中正而通达事理，正位居体，内在之美最终流布于言行并落实为事业。"}];return(q,e)=>{const d=a("DaoReadingPrelude"),l=a("DaoTextReading"),m=a("DaoKeywordCards");return c(),y("div",null,[e[0]||(e[0]=n("h1",{id:"文言传",tabindex:"-1"},[t("文言传 "),n("a",{class:"header-anchor",href:"#文言传","aria-label":'Permalink to "文言传"'},"​")],-1)),i(d,{title:"在每一个位置上，做合乎其时的事",summary:"《文言传》只解释乾、坤两卦，却把两卦的卦辞和爻辞展开成一套完整的修身与处世之学。乾讲创始、刚健、进德与知退；坤讲承载、柔顺、守正与成全。读它，不是只找吉凶，而是看人在不同位置上如何安顿自己。",points:[{label:"先读乾",text:"从元亨利贞与潜龙、见龙、飞龙，理解能力如何随时位展开。"},{label:"再读坤",text:"从至柔、含章、括囊与黄中，理解承载并不等于软弱或失去原则。"},{label:"合读",text:"乾坤不是两种互相排斥的人格，而是创始与完成、主动与承接的两面。"}],hint:"乾、坤都不是鼓励人永远向前或永远退让。真正的关键是：知道自己所处的时、位、势，并在其中做合乎其时的事。"}),e[1]||(e[1]=o('<h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>《文言传》是十翼中唯一专门解释乾、坤两卦的传。它先解释乾卦卦辞「元亨利贞」，再逐一申说乾卦六爻；坤卦则从「坤至柔，而动也刚」开始，展开坤道的承载、守正、含藏与成德。</p><p>它不是简单翻译卦辞，而是示范《易传》如何从一个卦象和一条爻辞中，读出德性、时位、行动和人的修养。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><ul><li>乾坤是六十四卦的门户。读懂二者的关系，其余卦的刚柔、时位、进退都有了参照。</li><li>「元亨利贞」被解释为善之长、嘉之会、义之和、事之干，说明卦辞可以展开为可实践的德性。</li><li>乾卦六爻展示一条完整的成长曲线：潜藏、显现、警醒、试跃、当位、过亢。</li><li>坤卦提醒人：柔顺可以有力量，安静可以有边界，不居功也可以把事情完成。</li></ul><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读乾、坤原文，不急着把龙、地、臣、妻等象直接套到现代身份上。</li><li>读乾时抓「时位」：潜、见、乾乾、跃、飞、亢不是简单的等级，而是不同处境下的行动要求。</li><li>读坤时抓「承载与守正」：至柔、含章、括囊、黄中都不是无条件退让。</li><li>将每条爻辞放回卦页，对照卦象、爻位与彖象；再区分经文、传文和现代个人理解。</li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>乾之四德</strong>：元为善之长，亨为嘉之会，利为义之和，贞为事之干；君子以体仁、合礼、利物、贞固来实践。</li><li><strong>乾之六位</strong>：潜龙勿用、见龙在田、终日乾乾、或跃在渊、飞龙在天、亢龙有悔，写出能力显隐与进退节律。</li><li><strong>乾之大人</strong>：与天地合德、与日月合明、与四时合序，先天而不违、后天而奉时。</li><li><strong>坤之道顺</strong>：坤至柔而动也刚，至静而德方，承天而时行；柔顺不是盲从，而是依规律完成自身工作。</li><li><strong>坤之修身</strong>：履霜知渐，敬以直内、义以方外，含章而不争功，括囊而知谨慎，黄中而发于事业。</li><li><strong>乾坤之极</strong>：亢龙有悔与龙战于野都说明，任何力量走到极端，都会失去原本的秩序。</li></ul><h2 id="与六十四卦的联动" tabindex="-1">与六十四卦的联动 <a class="header-anchor" href="#与六十四卦的联动" aria-label="Permalink to &quot;与六十四卦的联动&quot;">​</a></h2><ul><li>直接对照：<a href="/Dao/yijing/hexagrams/01-qianweitian"><code>乾卦</code></a> 与 <a href="/Dao/yijing/hexagrams/02-kunweidi"><code>坤卦</code></a> 的卦辞、彖辞、象辞和六爻。</li><li>读其他卦遇到「元亨利贞」时，可回到本文理解四德，而不只把它当成四个吉字。</li><li>「君子终日乾乾」「见几而作」「敬以直内，义以方外」可与<a href="/Dao/yijing/shi-yi/xi-ci-zhuan-xia"><code>系辞下传</code></a>的时位、忧患与行动主题互参。</li><li>「乾坤其《易》之门」也可与<a href="/Dao/yijing/shi-yi/shuo-gua-zhuan"><code>说卦传</code></a>的三才、八卦与取象体系对读。</li></ul><h2 id="【原典层】乾文言" tabindex="-1">【原典层】乾文言 <a class="header-anchor" href="#【原典层】乾文言" aria-label="Permalink to &quot;【原典层】乾文言&quot;">​</a></h2>',12)),i(l,{colophon:"元亨利贞 · 六龙时位 · 大人合天 · 知进知退",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"乾文言原文",sections:r,glossary:s}),e[2]||(e[2]=n("h2",{id:"【原典层】坤文言",tabindex:"-1"},[t("【原典层】坤文言 "),n("a",{class:"header-anchor",href:"#【原典层】坤文言","aria-label":'Permalink to "【原典层】坤文言"'},"​")],-1)),i(l,{colophon:"至柔动刚 · 承天时行 · 敬直义方 · 黄中通理",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"坤文言原文",sections:g,glossary:h}),e[3]||(e[3]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[t("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(m,{items:[{term:"元亨利贞",pinyin:["yuán","hēng","lì","zhēn"],meaning:"文言分别解释为善之长、嘉之会、义之和、事之干。四字不是四个孤立吉兆，而是一条从发端、通达、合宜到守正的成事结构。"},{term:"体仁",pinyin:["tǐ","rén"],meaning:"以仁为体，把仁落实为自身的行动，因此足以长养、成全他人，而不只是口头谈仁。"},{term:"贞固",pinyin:["zhēn","gù"],meaning:"守住原则与根本。「固」不是僵硬地拒绝变化，而是在方法变化时仍不失诚实、责任与分寸。"},{term:"潜龙",pinyin:["qián","lóng"],meaning:"德性与能力尚在隐伏、行动尚未完成的阶段。勿用不是不学习，而是不把未成熟强行推到台前。"},{term:"见龙",pinyin:["xiàn","lóng"],meaning:"德性开始显现并影响周围。其基础是庸言可信、庸行谨慎、善世而不自伐。"},{term:"知几",pinyin:["zhī","jī"],meaning:"知道事情将动未动的微小征兆。知至至之、知终终之，都是对时机和边界的辨认。"},{term:"大人",pinyin:["dà","rén"],meaning:"不是单指地位高的人，而是能与天地、日月、四时相合，先后皆能奉时而行的德性与担当。"},{term:"至柔动刚",pinyin:["zhì","róu","dòng","gāng"],meaning:"坤外在柔顺，实际行动却有承载和完成的力量。柔并不等于弱，静也不等于没有方向。"},{term:"承天时行",pinyin:["chéng","tiān","shí","xíng"],meaning:"承接规律并依时行动，不是盲从天意，而是看清条件、角色和时势后完成自己的工作。"},{term:"含章",pinyin:["hán","zhāng"],meaning:"内有才华、美德和光明，却不急于显露或争功。含不是压抑才能，而是不让自我证明取代事情本身。"},{term:"括囊",pinyin:["kuò","náng"],meaning:"扎紧袋口，象征天地闭塞或时机不宜时的谨慎收敛；不能把它滥用为逃避应尽责任的借口。"},{term:"黄中通理",pinyin:["huáng","zhōng","tōng","lǐ"],meaning:"内守中正而通达事理，正位居体，内在之美最终流布于言行并落实为事业。"}]}),e[4]||(e[4]=o('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><blockquote><p>这两篇最适合对照阅读：不把乾、坤简化成性格标签，而是观察创始与承载如何在不同位置上互相成就。</p></blockquote><h3 id="象-乾坤两篇在说什么" tabindex="-1">象：乾坤两篇在说什么 <a class="header-anchor" href="#象-乾坤两篇在说什么" aria-label="Permalink to &quot;象：乾坤两篇在说什么&quot;">​</a></h3><p>乾文言把乾卦读成一条君子成长和行动的路径：有能力时先潜藏蓄力，开始显现时以日用诚信立身，处于中段时终日乾乾、进德修业，在跃迁关口先自试、待时，到了高位要使万物有所感应，到了极处则必须知道退。</p><p>坤文言则把坤卦读成一种承事成物的力量：外在柔顺，实际行动刚健；内心安静，却有方正边界；不抢先，却能找到主线和自己的位置；有美而含章，闭塞时知谨慎，内在德性最终畅于四支、发于事业。</p><h3 id="理-为什么乾坤必须合读" tabindex="-1">理：为什么乾坤必须合读 <a class="header-anchor" href="#理-为什么乾坤必须合读" aria-label="Permalink to &quot;理：为什么乾坤必须合读&quot;">​</a></h3><ul><li>乾只讲向上，容易变成逞强；坤只讲顺从，容易变成失去主见。两篇放在一起，才看见主动与承接的完整循环。</li><li>乾的「贞」是做事的骨干，坤的「方」是行动的边界；一个守主干，一个定尺度。</li><li>乾强调「与时偕行」，坤强调「承天时行」；一个是主动随时而进，一个是承接条件而完成。</li><li>乾、坤走到极处都出现警告：亢龙会悔，阴阳疑而战；力量若失去位置，便会从成事转为失序。</li></ul><h3 id="用-今天怎么读自己的位置" tabindex="-1">用：今天怎么读自己的位置 <a class="header-anchor" href="#用-今天怎么读自己的位置" aria-label="Permalink to &quot;用：今天怎么读自己的位置&quot;">​</a></h3><p>可以带着四个问题读乾坤：</p><ul><li>我现在是在潜藏积累、开始显现、过渡试跃，还是已经需要知退？</li><li>我手里是否已有足够的器与能力，还是急着证明自己已经到了「飞龙在天」？</li><li>我是否把柔顺误当成退缩，把谨慎误当成逃避，把不争功误当成不需要维护正当贡献？</li><li>当前最需要的是乾的启动和担当，还是坤的承接、边界、养护与完成？</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>乾像一股向前的力量：它会开始、推进、承担，也会在每个阶段重新判断自己是否合时。它不鼓励永远冲刺，而是要求人在潜藏、显现、试探、当位和极盛之间保持清醒。</p><p>坤像一块能够承事的土地：它不急着争先，却能承接方向；不大声证明，却能把事情养成；不因柔和而放弃边界，也不因不居功而放弃完成。</p><p>一个人真正成熟，也许不是更像乾或更像坤，而是知道什么时候需要哪一种力量：用乾打开局面，用坤让局面落地；用乾守住担当，用坤守住分寸；最后让刚健与柔顺共同服务于一件可以长久的事。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：《文言》把乾、坤两卦讲透了，我才明白「刚」与「柔」不是二选一——乾讲创始、坤讲承接，二者合起来才是一条完整的事；柔不是弱，安静的承载同样能生出刚健而持久的结果。</p></blockquote><p>这次整理留下三点：</p><ul><li>乾坤的重点不在二选一。乾讲主动创始，坤讲承接完成，二者都是完整秩序不可缺少的一面。</li><li>乾的“知进退存亡”，与坤的“承天而时行”都在说明：方法可以变化，但不能失去对时、位、责任和根本的辨认。</li><li>“柔”不等于弱，“不争”也不等于没有价值。只要敬义立、内外有方，安静的承载同样能够产生刚健而持久的结果。</li></ul><h2 id="延伸阅读-参考来源" tabindex="-1">延伸阅读 / 参考来源 <a class="header-anchor" href="#延伸阅读-参考来源" aria-label="Permalink to &quot;延伸阅读 / 参考来源&quot;">​</a></h2><ul><li>十翼总览：<a href="/Dao/yijing/shi-yi/"><code>孔子十翼</code></a></li><li>乾卦：<a href="/Dao/yijing/hexagrams/01-qianweitian"><code>文王六十四卦·乾</code></a></li><li>坤卦：<a href="/Dao/yijing/hexagrams/02-kunweidi"><code>文王六十四卦·坤</code></a></li><li>相关原典：<a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang"><code>系辞上传</code></a>、<a href="/Dao/yijing/shi-yi/shuo-gua-zhuan"><code>说卦传</code></a></li><li>通行本《周易·文言传》（王弼注、孔颖达疏系统）</li></ul>',20))])}}});export{f as __pageData,k as default};
